import React, { useMemo, useState } from 'react';
import { Table, TableHead, TableRow, TableHeaderCell, TableBody, TableCell, Badge, Pagination } from '@jinx-ui/react';

export interface User {
  id: string;
  name: string;
  role: string;
  status: 'active' | 'disabled';
}

interface UsersTableProps {
  users: User[];
}

const PAGE_SIZE = 10;

const UsersTable: React.FC<UsersTableProps> = ({ users }) => {
  const [page, setPage] = useState(1);

  const pageCount = Math.max(1, Math.ceil(users.length / PAGE_SIZE));

  const currentUsers = useMemo(() => {
    const start = (page - 1) * PAGE_SIZE;
    return users.slice(start, start + PAGE_SIZE);
  }, [users, page]);

  return (
    <div className="jx-stack jx-stack-gap-md">
      <Table>
        <TableHead>
          <TableRow>
            <TableHeaderCell>Имя</TableHeaderCell>
            <TableHeaderCell>Роль</TableHeaderCell>
            <TableHeaderCell>Статус</TableHeaderCell>
          </TableRow>
        </TableHead>
        <TableBody>
          {currentUsers.map((user) => (
            <TableRow key={user.id}>
              <TableCell>{user.name}</TableCell>
              <TableCell>{user.role}</TableCell>
              <TableCell>
                <Badge tone={user.status === 'active' ? 'success' : 'neutral'}>
                  {user.status === 'active' ? 'Активен' : 'Отключён'}
                </Badge>
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
      <Pagination
        page={page}
        pageCount={pageCount}
        onPageChange={setPage}
      />
    </div>
  );
};

export default UsersTable;

